```python
def impute_nan(dataset, strategy="mean"):
  for row in range(dataset.shape[0]):
    for col in range(dataset.shape[1]):
      if np.isnan(dataset[row, col]):
        if strategy == "mean":
          dataset[row, col] = dataset[:, col].mean()
  return dataset
```

