def get_char_frequency(sentence):
    freq_dict = {}
    for ch in sentence:
        if ch in freq_dict:
            freq_dict[ch] += 1
        else:
            freq_dict[ch] = 1
    return freq_dict

# main
if __name__ == \'__main__\':
    sentence = "This is a test sentence."
    freq_dict = get_char_frequency(sentence)
    for ch in freq_dict:
